package com.aistock.scheduler.adminrefresh;
import com.aistock.common.*;import com.aistock.common.adminrefresh.AdminMarketRefreshRecords.*;import com.aistock.scheduler.security.*;import com.fasterxml.jackson.databind.ObjectMapper;import jakarta.servlet.http.Cookie;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import org.springframework.test.web.servlet.*;import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class AdminMarketRefreshHttpTest {
 final UUID actor=UUID.fromString("00000000-0000-0000-0000-000000000001"),op=UUID.fromString("00000000-0000-0000-0000-000000000002");final Instant now=Instant.parse("2026-10-27T12:00:00Z");final String root="/api/v1/admin/market-data/SH600030",origin="http://127.0.0.1:15173";final Cookie cookie=new Cookie("AISTOCK_SESSION","session");AdminMarketRefreshService service;SessionIdentityClient identity;MockMvc mvc;
 final String body="{\"operationId\":\"00000000-0000-0000-0000-000000000002\",\"baseVersionId\":\"11111111-1111-1111-1111-111111111111\",\"expectedHeadRevision\":\"7\",\"targetDate\":\"2026-10-27\",\"reasonCode\":\"RECHECK_DATA\"}";
 @BeforeEach void init(){service=mock(AdminMarketRefreshService.class);identity=mock(SessionIdentityClient.class);when(identity.resolve(any(),anyString())).thenReturn(ApiResponse.success(new SessionIdentityClient.Identity(actor,"ADMIN",false,1),"t"));var mapper=new ObjectMapper().findAndRegisterModules();var cors=new AdminMarketRefreshSecurityConfiguration();mvc=MockMvcBuilders.standaloneSetup(new AdminMarketRefreshController(service,Clock.fixed(now,ZoneOffset.UTC))).setControllerAdvice(new ApiExceptionHandler()).addFilters(cors.adminMarketRefreshCors(origin).getFilter(),new AdminTaskAccessFilter(identity,"test",mapper,Set.of(origin))).build();}
 @Test void authenticatesReadsAndRejectsUserBeforeService()throws Exception{mvc.perform(get(root+"/refresh-options")).andExpect(status().isUnauthorized());when(identity.resolve(any(),anyString())).thenReturn(ApiResponse.success(new SessionIdentityClient.Identity(actor,"USER",false,1),"t"));mvc.perform(get(root+"/refresh-options").cookie(cookie).header("X-Role","ADMIN")).andExpect(status().isForbidden());verifyNoInteractions(service);}
 @Test void commandUsesAuthoritativeActorAndKeeps409Receipt()throws Exception{var receipt=new Receipt(op.toString(),"SH600030",actor.toString(),"REJECTED","REFRESH_ACTIONS_DISABLED",null,"11111111-1111-1111-1111-111111111111","7",null,LocalDate.of(2026,10,27),"RECHECK_DATA",now,now,false);when(service.submit(eq(actor),eq("SH600030"),any(),eq(now))).thenReturn(new Submission(409,"REFRESH_ACTIONS_DISABLED",receipt));mvc.perform(post(root+"/refresh-operations").cookie(cookie).header("Origin",origin).header("X-Aistock-Admin-Action","1").contentType("application/json").content(body)).andExpect(status().isConflict()).andExpect(jsonPath("$.data.operationId").value(op.toString())).andExpect(header().string("Cache-Control","no-store"));}
 @Test void strictQueriesBodiesAndMethodsDoNotReachService()throws Exception{mvc.perform(get(root+"/refresh-options").cookie(cookie).content("{}")).andExpect(status().isBadRequest());mvc.perform(get(root+"/refresh-operations").cookie(cookie).param("size","20","20")).andExpect(status().isBadRequest());mvc.perform(post(root+"/refresh-operations").cookie(cookie).header("Origin",origin).header("X-Aistock-Admin-Action","1").contentType("application/json").content(body.replace("\"7\"","7"))).andExpect(status().isBadRequest());mvc.perform(post(root+"/refresh-operations").cookie(cookie).contentType("application/json").content(body)).andExpect(status().isForbidden());mvc.perform(delete(root+"/refresh-options").cookie(cookie)).andExpect(status().isNotFound());verifyNoInteractions(service);}
 @Test void preflightIsReadOnly()throws Exception{mvc.perform(options(root+"/refresh-operations").header("Origin",origin).header("Access-Control-Request-Method","POST").header("Access-Control-Request-Headers","Content-Type,X-Aistock-Admin-Action")).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store"));verifyNoInteractions(identity,service);}
}
